def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    for color in counts:
        if color == background:
            continue

        cells = [(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == color]
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)

        if r1 - r0 < 2 or c1 - c0 < 2:
            continue

        perimeter = (
            [(r0, c) for c in range(c0, c1 + 1)] +
            [(r1, c) for c in range(c0, c1 + 1)] +
            [(r, c0) for r in range(r0, r1 + 1)] +
            [(r, c1) for r in range(r0, r1 + 1)]
        )
        if not all(grid[r][c] == color for r, c in perimeter):
            continue

        inner_h, inner_w = r1 - r0 - 1, c1 - c0 - 1
        fill = 2 if inner_h % 2 == 0 and inner_w % 2 == 0 else 7
        for r in range(r0 + 1, r1):
            for c in range(c0 + 1, c1):
                if grid[r][c] == background:
                    out[r][c] = fill

    return out
